        angle_arg = adcs_quat_abs_dot(&ref_q, &qn);
        if (angle_arg > 1.0) angle_arg = 1.0;
        if (angle_arg < 0.0) angle_arg = 0.0;
        sh_output.relative_step_rad = 2.0 * acos(angle_arg);
        sh_state.mode = SH_TRACK;
        sh_state.dropouts = 0U;
        sh_state.last_q_bi = qn;
        sh_output.mode = sh_state.mode;
        sh_output.dropouts = sh_state.dropouts;
        sh_output.q_bi = sh_state.last_q_bi;
        return;
    }

    /* E: rejected */
    sh_state.dropouts += 1U;
    if (sh_state.dropouts <= sh_config.max_hold_cycles) {
        sh_state.mode = SH_HOLD;
    } else {
        sh_state.mode = SH_FAULT;
    }
    sh_output.mode = sh_state.mode;
    sh_output.dropouts = sh_state.dropouts;
    sh_output.q_bi = sh_state.last_q_bi;
    sh_output.relative_step_rad = 0.0;
}

